;(function(){
  var CUBE_HOST_ID = "tf-cube-field";

  function tfBoot(){
    if (document.getElementById(CUBE_HOST_ID)) return;

    var host = document.createElement("div");
    host.id = CUBE_HOST_ID;
    // zIndex 5: fica acima dos fundos decorativos (zIndex 0) mas atrás
    // dos painéis/conteúdo do app (zIndex 10), então nunca sobrepõe a UI.
    host.style.cssText = "position:fixed;inset:0;pointer-events:none;z-index:5;overflow:hidden;";
    document.body.insertBefore(host, document.body.firstChild);

    var cubes = [];
    var lastSpawn = 0;

    function spawnCube(){
      var size = 14 + Math.random() * 26;
      var el = document.createElement("div");
      el.style.cssText = "position:absolute;left:0;top:0;width:" + size + "px;height:" + size + "px;"
        + "background:linear-gradient(135deg, rgba(217,122,44,0.55), rgba(217,122,44,0.08));"
        + "border:1px solid rgba(255,180,84,0.55);border-radius:2px;"
        + "box-shadow:0 0 6px rgba(217,122,44,0.35);"
        + "mix-blend-mode:screen;will-change:transform;";
      host.appendChild(el);
      var vw = window.innerWidth;
      cubes.push({
        el: el,
        size: size,
        x: Math.random() * vw,
        y: -60,
        vy: 42 + Math.random() * 50,
        vx: (Math.random() * 30) - 15,
        rot: Math.random() * 360,
        vr: (Math.random() * 60) - 30,
        dead: false
      });
    }

    var lastTs = 0;
    function loop(ts){
      requestAnimationFrame(loop);
      if (!lastTs) lastTs = ts;
      var dt = Math.min((ts - lastTs) / 1000, 0.05);
      lastTs = ts;

      if (ts - lastSpawn > 420) {
        lastSpawn = ts;
        spawnCube();
      }

      for (var i = cubes.length - 1; i >= 0; i--) {
        var c = cubes[i];
        c.y += c.vy * dt;
        c.x += c.vx * dt;
        c.rot += c.vr * dt;
        if (c.y > window.innerHeight + 60) {
          if (c.el.parentNode) c.el.parentNode.removeChild(c.el);
          cubes.splice(i, 1);
          continue;
        }
        c.el.style.transform = "translate(" + c.x + "px," + c.y + "px) rotate(" + c.rot + "deg)";
      }
    }
    requestAnimationFrame(loop);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", tfBoot);
  } else {
    tfBoot();
  }
})();

